SELECT COUNT(*)
FROM GYE_MEMBER
WHERE GROUP_ID = #{groupId}
  AND MEMBER_ID = #{memberId}
  AND STATUS = 'ACTIVE'

SELECT AGREED_YN
FROM CONSENT
WHERE GROUP_ID = #{groupId}
  AND TARGET_ID = #{transferId}
  AND CONSENT_TYPE = 'TRANSFER'
  AND MEMBER_ID = #{memberId}

mapper.update:
UPDATE LEADER_TRANSFER_REQUEST
SET STATUS = 'CANCELLED',
    DECIDED_AT = SYSDATE
WHERE TRANSFER_ID = #{transferId}
  AND GROUP_ID = #{groupId}
  AND STATUS = 'PENDING'

UPDATE GYE_GROUP
SET OWNER_ID = #{newId},
    UPDATED_AT = SYSDATE
WHERE GROUP_ID = #{groupId}
  AND OWNER_ID = #{oldId}
